    /* 2026-08-27：人体感应状态 + 距离（LD2410B，P124 迁 /dev/uart3）
     * 2026-08-28 诊断期：每秒打印 [prox] 日志（lbl 是否存在 + p/dist/
     * seated），放 if 外——即使 standby_prox_lbl 未创建也能看到数据
     * 链路，区分「数据问题 vs label 指针问题」（确认后删） */
    {
        int p = dm_ld2410b_present();
        int dist = dm_ld2410b_get_dist_cm();
        LV_LOG_USER("[prox] refresh lbl=%d p=%d dist=%d seated=%d",
                    standby_prox_lbl ? 1 : 0, p, dist,
                    dm_health_is_seated() ? 1 : 0);
        if (standby_prox_lbl)
        {
            if (p < 0)
                lv_label_set_text(standby_prox_lbl, "人体：不可用");
            else if (p == 0)
                lv_label_set_text(standby_prox_lbl, "人体：无人");
            else
            {
                /* 有人：附带探测距离（0.75m 距离门分辨率，显示到 0.1m；
                 * 2026-08-28：dist=0 = 目标在最近距离门内（<0.75m），
                 * 也必须显示距离——原 dist>0 判断会让它退化成"人体：有人"；
                 * 显示用整数拼接（LVGL builtin lv_snprintf 不支持 %f，
                 * CONFIG_LV_USE_FLOAT 未启用——温度显示同款惯例） */
                if (dist >= 0)
                {
                    lv_snprintf(buf, sizeof(buf), "人体：有人 %d.%dm",
                                dist / 100, (dist % 100) / 10);
                    lv_label_set_text(standby_prox_lbl, buf);
                }
                else
                    lv_label_set_text(standby_prox_lbl, "人体：有人");
            }
            /* 2026-08-28 诊断：fmtlen=lv_snprintf 输出字节数（20=完整
             * "人体：有人 0.5m"；9=截断只"人体："）；lbl w 若仍≈52 且
             * fmtlen=20 → flex 缓存宽度问题（确认后删） */
            {
                lv_obj_t *hp = lv_obj_get_parent(standby_prox_lbl);
                LV_LOG_USER("[prox] fmtlen=%d lbl w=%d h=%d | hp x=%d y=%d",
                            (int)lv_strlen(buf),
                            (int)lv_obj_get_width(standby_prox_lbl),
                            (int)lv_obj_get_height(standby_prox_lbl),
                            (int)lv_obj_get_x(hp), (int)lv_obj_get_y(hp));
            }
        }
    }
}

