41	/* Audio gain multiplier to compensate for multi-channel DMIC mixing.
42	 * When board configures 6 DMIC channels but only 1 has a physical mic,
43	 * the mono mix dilutes the signal by ~6x. Set gain to compensate.
44	 * Configurable via CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN in Kconfig.
45	 * 2026-08-15 P75：×12 仍不足——上板 T5 chunk peak 仅 768（原始信号 ~64，
46	 * -54dBFS），服务器 VAD 判无语音 → ASR -104/-61。×32 后 768→2048 过
47	 * 2000 阈值；clamp ±32767 防削波。 */
48	#ifdef CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
49	#define AGENT_AUDIO_CAPTURE_GAIN CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
50	#else
51	#define AGENT_AUDIO_CAPTURE_GAIN 32
52	#endif
53	
54	/* 板级 PCM 卡名：与 luncher_dm dm_sound_open 一致（CONFIG_AW_AUDIO_CODEC=y） */
55	#define AGENT_CAPTURE_CARD "hw:audiocodec"
56	
57	/* 捕获 buffer 参考 arecord：period 1024 / buffer 4096 帧 */
58	#define AGENT_CAPTURE_PERIOD 1024
59	#define AGENT_CAPTURE_BUFFER 4096
60	
61	struct audio_capture {
62	    snd_pcm_t* pcm;
63	    unsigned int sample_rate;
64	    unsigned int channels;
65	    unsigned int bits_per_sample;
66	};
