68	audio_capture_t* audio_capture_open(const char* dev_path,
69	    unsigned int sample_rate, unsigned int channels,
70	    unsigned int bits_per_sample)
71	{
72	    (void)dev_path; /* aw-alsa-lib 按卡名路由，无需设备路径 */
73	
74	    /* 2026-08-11 P56+ 修复：集成 MIC（MICIN1P/MICIN1N + MBIAS → ADC1）。
75	     * codec 默认 MIC_PGA_EN（MIC1 input switch）关闭 → sunxi_get_adc_ch()
76	     * 返回 -1 → capture hw_params 报 "only support 1~3 channel" -22。
77	     * 先经 snd_ctl 打开 ADC1 MIC 通路 + 增益（参考 HAL aloop 测试写法）。
78	     * 2026-08-12 提高增益：上板实测轻声录音 peak 仅 200± → 服务器 VAD
79	     * 判无语音（text:"" / duration:0）。MIC1 gain volume mask 0x1F（0~31，
80	     * codec 默认 .mic1gain=0x1f），从 19 提到 31（最大 PGA 增益）。 */
81	    snd_ctl_set("audiocodec", "MIC1 gain volume", 31);
82	    snd_ctl_set("audiocodec", "MIC1 input switch", 1);
83	    snd_ctl_set("audiocodec", "MIC2 input switch", 0);
84	    snd_ctl_set("audiocodec", "MIC3 input switch", 0);
85	
86	    snd_pcm_t* handle = NULL;
87	    snd_pcm_hw_params_t* params = NULL;
88	    snd_pcm_uframes_t period = AGENT_CAPTURE_PERIOD;
89	    snd_pcm_uframes_t buffer = AGENT_CAPTURE_BUFFER;
90	    int ret;
91	
92	    ret = snd_vela_pcm_open(&handle, AGENT_CAPTURE_CARD,
93	        SND_VELA_PCM_STREAM_CAPTURE, 0);
94	    if (ret < 0) {
95	        syslog(LOG_ERR, "[%s] snd_vela_pcm_open(%s, CAPTURE) fail %d\n",
96	            TAG, AGENT_CAPTURE_CARD, ret);
97	        return NULL;
98	    }
99	
100	    snd_vela_pcm_hw_params_malloc(&params);
101	    ret = snd_vela_pcm_hw_params_any(handle, params);
102	    if (ret < 0) {
103	        syslog(LOG_ERR, "[%s] hw_params_any fail %d\n", TAG, ret);
104	        goto err;
105	    }
106	
107	    snd_vela_pcm_hw_params_set_access(handle, params,
108	        SND_PCM_ACCESS_RW_INTERLEAVED);
109	    snd_vela_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S16_LE);
110	    snd_vela_pcm_hw_params_set_channels(handle, params, channels);
111	    snd_vela_pcm_hw_params_set_rate(handle, params, sample_rate, 0);
112	    snd_vela_pcm_hw_params_set_period_size(handle, params, period, 0);
113	    snd_vela_pcm_hw_params_set_buffer_size(handle, params, buffer);
114	
115	    ret = snd_vela_pcm_hw_params(handle, params);
116	    snd_vela_pcm_hw_params_free(params);
117	    params = NULL;
118	    if (ret < 0) {
119	        syslog(LOG_ERR, "[%s] hw_params fail %d\n", TAG, ret);
120	        goto err;
121	    }
122	
123	    /* SW params：捕获 start_threshold=1（有数据即自动启动），
124	     * 参考 arecord set_param 的 CAPTURE 分支。 */
125	    {
126	        snd_pcm_sw_params_t* sw;
127	        snd_pcm_sw_params_alloca(&sw);
128	        snd_vela_pcm_sw_params_current(handle, sw);
129	        snd_vela_pcm_sw_params_set_start_threshold(handle, sw, 1);
130	        snd_vela_pcm_sw_params_set_stop_threshold(handle, sw, buffer);
131	        snd_vela_pcm_sw_params_set_avail_min(handle, sw, period);
132	        ret = snd_vela_pcm_sw_params(handle, sw);
133	        if (ret < 0) {
134	            syslog(LOG_ERR, "[%s] sw_params fail %d\n", TAG, ret);
135	            goto err;
136	        }
137	    }
138	
139	    audio_capture_t* cap = calloc(1, sizeof(*cap));
140	
141	    if (!cap) {
142	        goto err;
143	    }
144	
145	    cap->pcm = handle;
146	    cap->sample_rate = sample_rate;
147	    cap->channels = channels;
148	    cap->bits_per_sample = bits_per_sample;
149	
150	    syslog(LOG_INFO,
151	        "[%s] opened %s capture (%uHz %uch %ubit)\n",
152	        TAG, AGENT_CAPTURE_CARD, sample_rate, channels, bits_per_sample);
153	    return cap;
154	
155	err:
156	    if (params) {
157	        snd_vela_pcm_hw_params_free(params);
158	    }
159	
160	    if (handle) {
161	        snd_vela_pcm_close(handle);
162	    }
163	
164	    return NULL;
165	}
