167	int audio_capture_start(audio_capture_t* cap)
168	{
169	    if (!cap || !cap->pcm) {
170	        return -EINVAL;
171	    }
172	
173	    int ret = snd_vela_pcm_prepare(cap->pcm);
174	
175	    if (ret < 0) {
176	        syslog(LOG_ERR, "[%s] prepare fail %d\n", TAG, ret);
177	        return ret;
178	    }
179	
180	    syslog(LOG_INFO, "[%s] capture started\n", TAG);
181	    return 0;
182	}
