184	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
185	{
186	    if (!cap || !cap->pcm || !buf || len == 0) {
187	        return -EINVAL;
188	    }
189	
190	    int frame_bytes = (int)cap->channels * ((int)cap->bits_per_sample / 8);
191	    snd_pcm_uframes_t frames = (snd_pcm_uframes_t)(len / (size_t)frame_bytes);
192	    snd_pcm_sframes_t n;
193	    int retries = 0;
194	
195	    if (frames == 0) {
196	        return -EINVAL;
197	    }
198	
199	    /* EAGAIN 短暂重试；EPIPE（xrun）prepare 恢复后重读 */
200	    for (;;) {
201	        n = snd_vela_pcm_readi(cap->pcm, buf, frames);
202	        if (n == -EAGAIN && retries < 10) {
203	            usleep(10 * 1000);
204	            retries++;
205	            continue;
206	        } else if (n == -EPIPE) {
207	            syslog(LOG_WARNING, "[%s] xrun, recovering\n", TAG);
208	            snd_vela_pcm_prepare(cap->pcm);
209	            if (retries < 10) {
210	                retries++;
211	                continue;
212	            }
213	        }
214	
215	        break;
216	    }
217	
218	    if (n < 0) {
219	        syslog(LOG_ERR, "[%s] readi fail %ld\n", TAG, (long)n);
220	        return (int)n;
221	    }
222	
223	    size_t got = (size_t)n * (size_t)frame_bytes;
224	
225	    /* Apply gain to compensate for multi-channel DMIC mixing.
226	     * When 6 DMIC channels are configured but only 1 has a physical mic,
227	     * the mono downmix dilutes the signal. Amplify to restore level. */
228	#if AGENT_AUDIO_CAPTURE_GAIN > 1
229	    if (got > 0) {
230	        int16_t* samples = (int16_t*)buf;
231	        int sample_count = (int)got / 2;
232	
233	        /* 2026-08-15 P78 修复（上板诊断实锤）：原硬 clamp ±32767 在
234	         * ×32 增益 + 大声说话时削波（chunk#9/10 peak=32768 满幅，波形
235	         * 削平 → ASR 识别不出 text）。改折线软限幅：超过 SOFT_CLIP
236	         * 部分衰减，保留 ×32 增益（batch P75 能量阈值 <2000 不受影响，
237	         * stream 大声不再削平波形）。 */
238	        const int32_t SOFT_CLIP = 20000;
239	
240	        for (int i = 0; i < sample_count; i++) {
